flow.yaml:
name: worker-root
on: [manual]
steps:
  install: { stage: check, run: "npm ci", needs: [] }
  dry-run: { stage: check, run: "npx wrangler deploy --dry-run --outdir dist", needs: [install] }

name: terraform-infra
on: [manual]
steps:
  init: { stage: check, run: "cd 'infra' && terraform init -backend=false", needs: [] }
  plan: { stage: check, run: "cd 'infra' && terraform plan -refresh=false -input=false", needs: [init] }
